beforeExample:
import java.text.MessageFormat;

public class Example {
    public static void main(String[] args) {
        String name = "World";
        String greeting = MessageFormat.format("Hello, {0}!", new String[]{name});
        System.out.println(greeting);
    }
}

afterExample:
import java.text.MessageFormat;

public class Example {
    public static void main(String[] args) {
        String name = "World";
        String greeting = MessageFormat.format("Hello, {0}!", new Object[]{name});
        System.out.println(greeting);
    }
}

negativeExample:
import java.text.MessageFormat;

public class Example {
    public static void main(String[] args) {
        Object[] data = new Object[]{"hello", 123}; // Already Object[]
        System.out.println(MessageFormat.format("Value: {0}", data));

        String[] names = new String[]{"Alice", "Bob"}; // Not passed to MessageFormat.format
        System.out.println(names[0]);
    }
}
